CREATE TABLE cards (id INTEGER PRIMARY KEY AUTOINCREMENT,sync_key TEXT NOT NULL UNIQUE,external_id TEXT NOT NULL,type TEXT NOT NULL,front TEXT NOT NULL,back TEXT NOT NULL,front_language TEXT NOT NULL,back_language TEXT NOT NULL,phonetic TEXT NOT NULL DEFAULT '',technical_notes TEXT NOT NULL DEFAULT '[]',context TEXT NOT NULL DEFAULT '',terms TEXT NOT NULL DEFAULT '[]',created_at INTEGER NOT NULL,content_updated_at INTEGER NOT NULL,encounter_count INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL DEFAULT 'new',due_at INTEGER NOT NULL,interval_days INTEGER NOT NULL DEFAULT 0,ease_factor REAL NOT NULL DEFAULT 2.5,repetitions INTEGER NOT NULL DEFAULT 0,lapses INTEGER NOT NULL DEFAULT 0,last_reviewed_at INTEGER NOT NULL DEFAULT 0,archived_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX cards_due_idx ON cards(archived_at, due_at);
CREATE TABLE review_log (id INTEGER PRIMARY KEY AUTOINCREMENT,card_id INTEGER NOT NULL,rating TEXT NOT NULL,reviewed_at INTEGER NOT NULL,next_due_at INTEGER NOT NULL);
CREATE INDEX review_log_date_idx ON review_log(reviewed_at);